create table if not exists public.notification_channels (id bigint generated by default as identity primary key, name varchar(80) not null, provider varchar(20) not null, config_encrypted text not null, config_hint varchar(200) not null default '', enabled boolean not null default true, created_by bigint references public.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.notification_subscriptions (id bigint generated by default as identity primary key, name varchar(80) not null, channel_id bigint not null references public.notification_channels(id) on delete cascade, enabled boolean not null default true, minimum_severity varchar(20), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.notification_subscription_events (subscription_id bigint not null references public.notification_subscriptions(id) on delete cascade, event_name varchar(60) not null, primary key(subscription_id, event_name));
create table if not exists public.event_outbox (id bigint generated by default as identity primary key, event_name varchar(60) not null, module varchar(30) not null default '', severity varchar(20) not null default 'info', entity_type varchar(40), entity_id varchar(120), payload_json text not null, dedupe_key varchar(150), suppressed_count integer not null default 0, status varchar(20) not null default 'pending', occurred_at timestamptz not null default now(), processed_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.notification_deliveries (id bigint generated by default as identity primary key, outbox_id bigint not null references public.event_outbox(id) on delete cascade, subscription_id bigint not null references public.notification_subscriptions(id) on delete cascade, channel_id bigint not null references public.notification_channels(id) on delete cascade, provider varchar(20) not null, status varchar(20) not null default 'pending', attempt_count integer not null default 0, response_status integer, response_summary varchar(500), last_error varchar(500), next_retry_at timestamptz, sent_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists notification_channels_provider_idx on public.notification_channels(provider, enabled);
create index if not exists notification_subs_channel_idx on public.notification_subscriptions(channel_id, enabled);
create index if not exists notification_sub_events_name_idx on public.notification_subscription_events(event_name);
create index if not exists event_outbox_status_idx on public.event_outbox(status, created_at);
create index if not exists event_outbox_dedupe_idx on public.event_outbox(dedupe_key, occurred_at);
create index if not exists notification_del_status_idx on public.notification_deliveries(status, next_retry_at);
create index if not exists notification_del_outbox_idx on public.notification_deliveries(outbox_id);
alter table public.notification_channels enable row level security;
alter table public.notification_subscriptions enable row level security;
alter table public.notification_subscription_events enable row level security;
alter table public.event_outbox enable row level security;
alter table public.notification_deliveries enable row level security;
revoke all on table public.notification_channels, public.notification_subscriptions, public.notification_subscription_events, public.event_outbox, public.notification_deliveries from anon, authenticated;
